use serde :: { Deserialize , Serialize } ; use std :: collections :: HashMap ; use super :: * ; impl SixSigmaMetrics { # [doc = " Calculate sigma level from DPU"] pub fn calculate_sigma (& mut self) -> f64 { self . sigma_level = if self . dpu > 0.0 && self . dpu < 1.0 { 1.5 + ((- 2.0 * self . dpu . ln ()) . sqrt ()) } else if self . dpu >= 1.0 { 1.5 } else { 6.0 } ; self . sigma_level = self . sigma_level . min (6.0) . max (0.0) ; self . sigma_level } }